        "T1195.002",
        "T1195.001"
      ]
    },
    {
      "description": "Abuse of trusted identity tokens (OIDC) and cryptographic SLSA provenance certificates to sign malicious build artifacts.",
      "mitre_techniques": [
        "T1078.004",
        "T1553.002"
      ]
    },
    {
      "description": "Execution of malicious dependency installation scripts harvesting environment secrets and host credentials.",
      "mitre_techniques": [
        "T1059.001",
        "T1552.001"
      ]
    }
  ],
  "affected_packages": [
    "@tanstack/react-router",
    "@tanstack/react-query",
    "@tanstack/table"
  ],
